from typing import List

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        max_diag_sq = -1
        best_area = 0
        for l, w in dimensions:
            diag_sq = l * l + w * w
            area = l * w
            if diag_sq > max_diag_sq:
                max_diag_sq = diag_sq
                best_area = area
            elif diag_sq == max_diag_sq and area > best_area:
                best_area = area
        return best_area
```

